 void Construct(const FArguments& Args){World=Args._World;SetCanTick(true);ForceVolatile(true);SetCursor(EMouseCursor::Default);Portraits[0]=LoadImage(TEXT("PortraitSource.png"));Portraits[0].SetUVRegion(FBox2f({170.f/2048,151.f/726},{583.f/2048,546.f/726}));Portraits[1]=LoadImage(TEXT("PortraitAlternateSource.png"));Portraits[1].SetUVRegion(FBox2f({524.f/1672,257.f/941},{722.f/1672,444.f/941}));DataDir=FString(FPlatformProcess::UserSettingsDir())/TEXT("KOALITIC/WorkbenchV03");Verify=FParse::Param(FCommandLine::Get(),TEXT("WorkbenchVerify"));QA=FParse::Param(FCommandLine::Get(),TEXT("QAControl"));FParse::Value(FCommandLine::Get(),TEXT("Evidence="),Evidence);if(Evidence.IsEmpty())Evidence=FPaths::ProjectSavedDir()/TEXT("Verification");PersistenceRead=FParse::Param(FCommandLine::Get(),TEXT("PersistenceRead"));if(Verify||PersistenceRead)DataDir/=TEXT("VerificationKit");IFileManager::Get().MakeDirectory(*DataDir,true);Load();LoadKit();SeedKit();if(auto* Material=LoadObject<UMaterialInterface>(nullptr,TEXT("/Game/InterfaceMaterials/M_ProfileGlass.M_ProfileGlass"))){GlassMaterial.Reset(UMaterialInstanceDynamic::Create(Material,nullptr));GlassBrush.SetResourceObject(GlassMaterial.Get());GlassBrush.DrawAs=ESlateBrushDrawType::Image;}if(Verify){D=ProfileData();P=Presentation();Shared=Presentation();State=ProfileState();for(int I=0;I<ParamCount;I++)Overrides[I]=false;}K.Time=0;K.From=0;Started=FPlatformTime::Seconds();UE_LOG(LogTemp,Display,TEXT("WORKBENCH_READY Unreal 5.8 layered runtime; portrait assets=%d/%d; storage=%s"),Portraits[0].GetResourceObject()!=nullptr,Portraits[1].GetResourceObject()!=nullptr,*DataDir);}
