 void Tick(const FGeometry& G,double Now,float Dt)override{ResolveKit();if(DeferredAction>=0&&--DeferredFrames<=0){int Action=DeferredAction;DeferredAction=-1;Activate(Action);}if(K.Playing)K.Time+=FMath::Min(Dt,.1f);SeekEnd=FMath::Max(SeekEnd,FMath::Max(12.f,FMath::CeilToFloat(K.Time/6)*6));RealTime=FPlatformTime::Seconds()-Started;if(!TitleSet&&RealTime>.5f&&GEngine&&GEngine->GameViewport){if(auto Window=GEngine->GameViewport->GetWindow()){Window->SetTitle(FText::FromString(TEXT("KOALITIC | UI Workbench 0.3")));TitleSet=true;}}if(RealTime>3){FrameSum+=Dt;FrameCount++;MaxFrame=FMath::Max(MaxFrame,Dt);}if(State.AutoCollapse&&!State.Pinned&&!State.Hover)State.SetCompact(true,K.Time,!K.Playing);if(Verify)VerifyTick();if(PersistenceRead&&RealTime>3){Check(D.Name==TEXT("KIT VERIFY")&&D.XP==4990&&P.Entrance==1&&P.Exit==1,TEXT("Shared assignments survive packaged restart"));Check(Overrides[7]&&FMath::IsNearlyEqual(P.AmbientStrength,.33f)&&FMath::IsNearlyEqual(Shared.AmbientStrength,.81f),TEXT("Per-value override and shared preset survive packaged restart"));IFileManager::Get().MakeDirectory(*Evidence,true);FFileHelper::SaveStringToFile(Checks,*(Evidence/TEXT("restart-results.txt")));FGenericPlatformMisc::RequestExit(false);PersistenceRead=false;}if(QA&&RealTime-LastQA>.2f){LastQA=RealTime;FString Cmd;FString Path=Evidence/TEXT("command.txt");if(FFileHelper::LoadFileToString(Cmd,*Path)&&!Cmd.IsEmpty()){FFileHelper::SaveStringToFile(TEXT(""),*Path);ExecuteQA(Cmd);}}UpdateMaterial();Invalidate(EInvalidateWidgetReason::Paint);}
