 void Check(bool Pass,const FString& Label){Checks+=(Pass?TEXT("PASS "):TEXT("FAIL "))+Label+TEXT("\n");UE_LOG(LogTemp,Display,TEXT("WORKBENCH_CHECK %s %s"),Pass?TEXT("PASS"):TEXT("FAIL"),*Label);}
